function render(keepScroll){document.documentElement.lang=ui.lang;document.title=seoInfo().title;var desc=document.querySelector('meta[name="description"]');if(desc)desc.setAttribute('content',seoInfo().description);document.getElementById('app').innerHTML=header()+currentPage()+footer()+drawer()+'<div class="toast" id="toast"></div>';document.body.classList.toggle('lock',ui.drawer||ui.menu);if(!keepScroll)window.scrollTo(0,0)}
function closeAll(){ui.drawer=false;ui.menu=false;ui.mega=false;document.body.classList.remove('lock')}
function navigate(to){closeAll();ui.search=false;ui.gallery='product';history.pushState({},'',to);render()}
function toast(message){var box=document.getElementById('toast');if(box){box.textContent=message;box.classList.add('show');setTimeout(function(){if(box)box.classList.remove('show')},2300)}}
document.addEventListener('click',function(e){var button=e.target.closest('[data-action], [data-add], [data-change], [data-remove], [data-gallery]');if(button){var action=button.getAttribute('data-action');if(action==='mega'){ui.mega=!ui.mega;ui.search=false;render(true);return}if(action==='search'){ui.search=!ui.search;ui.mega=false;render(true);if(ui.search){var field=document.querySelector('.searchbar input');if(field)field.focus()}return}if(action==='cart'){ui.drawer=true;ui.menu=false;render(true);return}if(action==='mobile'){ui.menu=true;ui.drawer=false;render(true);return}if(action==='close'){closeAll();render(true);return}if(action==='lang'){ui.lang=ui.lang==='nl'?'en':'nl';var params=new URLSearchParams(location.search);if(ui.lang==='en')params.set('lang','en');else params.delete('lang');history.replaceState({},'',location.pathname+(params.toString()?'?'+params.toString():''));closeAll();render(true);return}if(button.hasAttribute('data-gallery')){ui.gallery=button.dataset.gallery==='kitchen'?'kitchen':'product';render(true);return}if(action==='qtyplus'||action==='qtyminus'){ui.qty=Math.min(20,Math.max(1,ui.qty+(action==='qtyplus'?1:-1)));var q=document.getElementById('qtyDisplay');if(q)q.textContent=ui.qty;return}if(button.hasAttribute('data-add')){var id=button.dataset.add;if(!PRODUCTS.some(function(x){return x.id===id}))return;ui.cart[id]=(ui.cart[id]||0)+(location.pathname.indexOf('/producten/')===0?ui.qty:1);save();ui.drawer=true;render(true);return}if(button.hasAttribute('data-change')){var pid=button.dataset.id;if(!PRODUCTS.some(function(x){return x.id===pid}))return;ui.cart[pid]=Math.max(0,(ui.cart[pid]||0)+Number(button.dataset.change));save();render(true);return}if(button.hasAttribute('data-remove')){delete ui.cart[button.dataset.remove];save();render(true);return}}var a=e.target.closest('a[href]');if(a){var href=a.getAttribute('href');if(href&&href.charAt(0)==='/'&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&!a.hasAttribute('download')){e.preventDefault();navigate(href);return}}if(ui.mega&&!e.target.closest('.mega,.navlink')){ui.mega=false;render(true)}});
document.addEventListener('change',function(e){if(e.target.id==='sort'){ui.sort=e.target.value;render(true)}if(e.target.name==='finish'||e.target.id==='mobileFinish'){ui.finish=e.target.value;render(true)}});
